{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required field")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list):
        raise ValueError("required_symbols must be a list")
    if any(not isinstance(symbol, str) or not symbol for symbol in required_symbols):
        raise ValueError("required symbols must be non-empty strings")
    if len(set(required_symbols)) != len(required_symbols):
        raise ValueError("required symbols must be unique")

    required_fields = {"id", "parent", "symbol", "depth", "removable", "utility"}
    by_id = {}
    root_ids = []
    for node in nodes:
        if not isinstance(node, dict) or not required_fields.issubset(node):
            raise ValueError("invalid node")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or not node_id:
            raise ValueError("node id must be a non-empty string")
        if node_id in by_id:
            raise ValueError("duplicate node id")
        if parent is not None and (not isinstance(parent, str) or not parent):
            raise ValueError("parent must be null or a non-empty string")
        if not isinstance(symbol, str) or not symbol:
            raise ValueError("symbol must be a non-empty string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)):
            raise ValueError("utility must be numeric")
        if not math.isfinite(utility):
            raise ValueError("utility must be finite")
        by_id[node_id] = node
        if parent is None:
            root_ids.append(node_id)

    if len(root_ids) != 1:
        raise ValueError("tree must have exactly one root")
    root_id = root_ids[0]
    if by_id[root_id]["depth"] != 0:
        raise ValueError("root depth must be zero")
    if by_id[root_id]["removable"]:
        raise ValueError("root must not be removable")

    children = {node_id: [] for node_id in by_id}
    for node_id, node in by_id.items():
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id or parent == node_id:
            raise ValueError("invalid parent reference")
        if node["depth"] != by_id[parent]["depth"] + 1:
            raise ValueError("inconsistent node depth")
        children[parent].append(node_id)

    visited = set()
    stack = [root_id]
    while stack:
        node_id = stack.pop()
        if node_id in visited:
            raise ValueError("tree contains a cycle")
        visited.add(node_id)
        stack.extend(children[node_id])
    if len(visited) != len(nodes):
        raise ValueError("tree is disconnected")

    represented = {node["symbol"] for node in nodes}
    if any(symbol not in represented for symbol in required_symbols):
        raise ValueError("a required symbol is not represented")

    required = set(required_symbols)
    retained = set(by_id)
    removal_order = []
    candidates = sorted(
        by_id.values(),
        key=lambda node: (-node["depth"], node["id"]),
    )

    for node in candidates:
        node_id = node["id"]
        if node_id == root_id or not node["removable"] or node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        remaining_symbols = {
            by_id[retained_id]["symbol"]
            for retained_id in retained
            if retained_id != node_id
        }
        if not required.issubset(remaining_symbols):
            continue
        retained.remove(node_id)
        removal_order.append(node_id)

    return {
        "retained_ids": sorted(retained),
        "removal_order": removal_order,
    }
"}
